/* Connected evaluation capabilities. Local sample persistence; production needs server authorization. */
let pdFeedback='';
let pdCategory='Behavioral',pdTemplatesOpen=true,pdView='',pdEmployee='',pdQuery='',pdStatus='All statuses',pdType='All types',pdFrom='',pdTo='',pdGoalEditor=null,pdGoalPreview=false,pdActuals={},pdLastScreen='';
const pdNow=()=>new Date().toISOString(),pdDate=()=>new Date().toLocaleDateString('en-CA'),pdLabel={Self:'Self-Assessment',Manager:'Managerial Assessment',HR:'HR Assessment',Peer:'Peer Assessment',Upward:'Upward Assessment'};
const pdOld={nav:roleNav,sidebar:pmsSidebar,pages:pmsAccessiblePages,render,templateList:urTemplateList,drawTemplates:urDrawTemplates,builder:urBuilder,start:urStartWizard,wizard:urWizardPage,validation:urCycleValidation,commit:urCommitCycle,generate:urGenerateAssignments,edit:urCanEdit,read:urCanRead,effective:urEffective,detail:urReviewDetail,open:urOpenReview,saveResponse:urSaveResponse,submit:urSubmitResponse,confirm:urConfirmSubmit,reopen:urReopen,results:urEmployeeResults,mean:urMean,dashboard:pmsDashboardData,reports:pmsReportsPage};
function pdScopedEmployees(){return data.employees.filter(e=>pmsGoalEmployeeInCompany(e)&&(urHr()||viewRole==='Manager'&&urTeam(e[0])))}
function pdCanJournal(id){return viewRole!=='Employee'&&pdScopedEmployees().some(e=>e[0]===id)}
function pdIndicator(name='',unit='Percentage',target=100,direction='Higher',met=5){return {id:urUid('ind'),name,description:'',unit,target,weight:25,direction,scoreMet:met,scoreBelow:2}}
function pdSeed(){
 UR.goalTemplates??=[];UR.journal??=[];
 if(UR.connectedEvaluationVersion)return;
 const indicators=[pdIndicator('On-time design deliverables','Percentage',95,'Higher',4.8),pdIndicator('Approved design tasks','Count',12,'Higher',4.5),pdIndicator('Design revisions due to specification errors','Count',3,'Lower',4.6),pdIndicator('Developer handoff completion','Percentage',100,'Higher',4.5)];
 const gt={id:'pd-design-goals',name:'UI/UX Designer Performance Indicators',description:'Delivery, accuracy, and developer handoff outcomes.',position:'UI/UX Designer',status:'Published',version:1,updated:'2026-11-01',indicators};UR.goalTemplates.push(gt);
 const competencies=['Communication','Teamwork','Accountability','Initiative','Adaptability'];
 const bt=urTemplate('Core Workplace Behaviors','Manager','General Performance',competencies.map(n=>urQuestion(n,'Rating','Workplace Competencies')));bt.id='pd-behaviors';UR.templates.push(bt);
 const stages=(start='2026-11-06')=>['Self','Manager','HR'].map((type,i)=>({id:urUid('stage'),name:pdLabel[type],type,deadline:[start,'2026-11-11','2026-11-15'][i],reviewer:type==='HR'?'HR-001':'',goalsTemplate:gt.id,behavioralTemplate:bt.id}));
 const cycle=(id,subject,status)=>({id,name:id==='pd-completed'?'Annual Performance Review 2026':'Sequential Performance Review 2026',description:'Role-specific goals and workplace behaviors, assessed in sequence.',type:'Standard Performance Review',periodStart:'2026-01-01',periodEnd:'2026-12-31',start:'2026-10-01',deadline:'2026-11-15',participants:[subject],groups:['Self','Manager','HR'],evaluators:[],templates:{},stages:stages(),weights:{goals:60,behavioral:40},status,released:status==='Completed',finalComments:{},threshold:3,anonymousPeer:true,anonymousUpward:true,created:urToday,sample:true});
 for(const [id,subject,state] of [['pd-completed','EMP-001','Completed'],['pd-active','EMP-003','Active']]){
  const c=cycle(id,subject,state);UR.cycles.push(c);pdGenerate(c);
  if(state==='Completed'){
   const ratings=[[5,5,4,4,5],[4,5,4,4,4],[4,5,4,4,4]];
   UR.assignments.filter(a=>a.cycle===id).forEach((a,i)=>{a.state='Completed';a.submitted=['2026-11-05','2026-11-10','2026-11-14'][i];a.finalized='2026-11-15';a.answers=Object.fromEntries(a.template.questions.map((q,j)=>[q.id,String(ratings[i][j])]));a.actuals=Object.fromEntries(a.goalsTemplate.indicators.map((x,j)=>[x.id,[98,12,2,100][j]]));a.feedback=i===1?'Maria consistently delivered high-quality design outputs and demonstrated strong collaboration with the development team. Continued improvement in documentation consistency will further strengthen her performance.':i===2?'The evaluation reflects strong overall performance, particularly in goal achievement and teamwork. Continued professional development is recommended to support future responsibilities.':''});
   c.finalized='2026-11-15';c.releasedAt='2026-11-16';
  }
 }
 for(const [date,type,title,description] of [['2026-10-05','Achievement','Design deliverables completed early','Successfully completed the assigned design deliverables ahead of the scheduled deadline.'],['2026-10-12','Performance Observation','Improved development coordination','Demonstrated improved coordination with the development team during the design handoff process.'],['2026-10-16','Coaching / Feedback','Documentation consistency','Discussed opportunities to improve documentation consistency across design deliverables.']])UR.journal.push({id:urUid('journal'),employee:'EMP-001',date,type,title,description,author:'MGR-001',created:date+'T09:00:00.000Z',cycle:'pd-completed'});
 UR.connectedEvaluationVersion=1;save();
}
roleNav=function(){const rows=pdOld.nav();if(viewRole!=='Employee')rows.splice(rows.findIndex(r=>r[0]==='Reports'),0,['202 Files','']);return rows};
function pdGoTemplates(category){if(!urHr())return;urGo(()=>{pdCategory=category;urTab='Templates';urScreen='list';pdView='';page='Reviews';urPreview=false;pmsReviewsOpen=true;pdTemplatesOpen=true;render()})}
pmsAccessiblePages=function(){return pdOld.pages().filter(p=>p.label!=='Templates').concat(urHr()?['Goals','Behavioral'].map(category=>({label:category+' Templates',parent:'Reviews / Templates',action:`pdGoTemplates('${category}')`,icon:'Reviews'})):[])};
pmsSidebar=function(){let html=pdOld.sidebar();if(!urHr()||pmsSidebarQuery.trim())return html;const active=page==='Reviews'&&urTab==='Templates';return html.replace(/<button type="button" class="pms-subitem [^"]*"[^>]*onclick="urGoTab\('Templates'\)">[\s\S]*?<\/button>/,`<div class="pd-template-nav"><button type="button" class="pms-subitem pd-template-parent" aria-expanded="${pdTemplatesOpen}" onclick="pdTemplatesOpen=!pdTemplatesOpen;render()"><span>Templates</span>${pmsChevron('pms-chevron')}</button><div ${pdTemplatesOpen?'':'hidden'}>${['Goals','Behavioral'].map(category=>`<button type="button" class="pms-subitem pd-template-child ${active&&pdCategory===category?'active':''}" ${active&&pdCategory===category?'aria-current="page"':''} onclick="pdGoTemplates('${category}')">${category} Templates</button>`).join('')}</div></div>`)};
function pdBack(action,label){return `<button class="pd-back textbtn" onclick="${action}">← ${esc(label)}</button>`}
function pdHead(title,description,actions=''){return `<div class="pagehead pd-pagehead"><div class="pd-heading-row"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="pd-header-actions">${actions}</div>`:''}</div></div>`}
const pdSplitHeaderBase=pmsSplitPageHeader;
pmsSplitPageHeader=function(){const back=document.querySelector('#content > .pd-back'),header=document.querySelector('#content > .pagehead');if(back&&header)header.prepend(back);pdSplitHeaderBase()};
function pdOptions(values,value){return values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}
function pdTable(headers,rows,key,total,draw){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No records match these filters.</td></tr>`}</tbody></table></div><div class="tablefoot"><span>${total?`Showing ${(pmsTablePages[key]-1)*pmsPageSize+1}–${Math.min(pmsTablePages[key]*pmsPageSize,total)} of ${total} records`:'Showing 0–0 of 0 records'}</span>${pmsPager(key,total,draw)}</div>`}
function pdSlice(key,rows,signature){const p=pmsTablePage(key,rows.length,signature);return rows.slice((p-1)*pmsPageSize,p*pmsPageSize)}
function pdClickable(action){return `tabindex="0" role="button" onclick="${action}" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();${action}}"`}
urTemplateList=function(){if(!urHr())return pdOld.templateList();if(pdCategory==='Behavioral')return pdOld.templateList().replaceAll('Review Templates','Behavioral Templates').replace('Create Template','Create Behavioral Template');const rows=UR.goalTemplates.filter(t=>(t.name+' '+t.position).toLowerCase().includes(pdQuery.toLowerCase())&&(pdTemplateTab==='All Templates'?(pdStatus==='All statuses'||t.status===pdStatus):t.status===pdTemplateTab));const visible=pdSlice('pd-templates',rows,JSON.stringify([pdQuery,pdStatus,pdTemplateTab]));return pdHead('Goals Templates','Define measurable, role-specific performance indicators.','<button class="primary" onclick="pdEditGoalTemplate()">Create Goals Template</button>')+pmsListingTabs('Goals template status',['All Templates','Draft','Published'],pdTemplateTab,'pmsSetTemplateTab')+`<section class="panel pms-list-panel"><div class="toolbar urtoolbar">${pmsToolbarSearch('Search template or position',pdQuery,"pdQuery=this.value;render()")}${pdTemplateTab==='All Templates'?pmsToolbarSelect('Status',pdStatus,['All statuses','Draft','Published','Archived'],"pdStatus=this.value;render()"):''}</div>${pdTable(['TEMPLATE NAME','APPLICABLE POSITION / ROLE','INDICATORS','STATUS','LAST UPDATED'],visible.map(t=>`<tr ${pdClickable(`${t.status==='Draft'?'pdEditGoalTemplate':'pdViewGoalTemplate'}('${t.id}')`)}><td><b>${esc(t.name)}</b><small>Version ${t.version}</small></td><td>${esc(t.position)}</td><td>${t.indicators.length}</td><td>${urBadge(t.status)}</td><td>${date(t.updated)}</td></tr>`).join(''),'pd-templates',rows.length,'render')}</section>`};
urDrawTemplates=function(){if(pdCategory!=='Goals')pdOld.drawTemplates()};
function pdEditGoalTemplate(id){if(!urHr())return;urGo(()=>{const old=UR.goalTemplates.find(t=>t.id===id);pdGoalEditor=old?urClone(old):{id:urUid('goal-tpl'),name:'',description:'',position:'',status:'Draft',version:1,indicators:[pdIndicator()]};if(old&&old.status==='Published'){pdGoalEditor.id=urUid('goal-tpl');pdGoalEditor.version++;pdGoalEditor.original=old.id;pdGoalEditor.status='Draft'}pdGoalPreview=false;pdView='goalBuilder';page='Reviews';urTab='Templates';urScreen='list';urDirty=false;render()})}
function pdViewGoalTemplate(id){if(!urHr())return;pdGoalEditor=urClone(UR.goalTemplates.find(t=>t.id===id));if(!pdGoalEditor)return;pdView='goalDetails';page='Reviews';urTab='Templates';urScreen='list';render()}
function pdGoalField(key,value){pdGoalEditor[key]=value;urDirty=true}
function pdSetIndicator(index,key,value){pdGoalEditor.indicators[index][key]=['target','weight','scoreMet','scoreBelow'].includes(key)?Number(value):value;urDirty=true}
function pdGoalTemplateErrors(t,publish){const errors=[];if(!t.name.trim()||!t.position.trim())errors.push('Enter the template name and applicable position.');if(publish){if(!t.indicators.length)errors.push('Add at least one indicator.');if(t.indicators.some(x=>!x.name.trim()||!Number.isFinite(x.target)||x.target<0||!Number.isFinite(x.weight)||x.weight<=0||![x.scoreMet,x.scoreBelow].every(n=>Number.isFinite(n)&&n>=1&&n<=5)))errors.push('Each indicator needs a name, nonnegative target, positive weight, and scores between 1 and 5.');if(Math.abs(t.indicators.reduce((sum,x)=>sum+x.weight,0)-100)>.01)errors.push('Indicator weights must total 100%.')}return errors}
function pdSaveGoalTemplate(state){if(!urHr()||!pdGoalEditor)return;const errors=pdGoalTemplateErrors(pdGoalEditor,state==='Published');if(errors.length){$('#pdGoalError').textContent=errors.join(' ');return}const t=urClone(pdGoalEditor);t.status=state;t.updated=urToday;delete t.original;const index=UR.goalTemplates.findIndex(x=>x.id===t.id);if(index>=0)UR.goalTemplates[index]=t;else UR.goalTemplates.push(t);urDirty=false;urAudit('Goals template '+state+': '+t.id);pdView='';render();toast('Goals template saved')}
function pdGoalTemplateAction(action){if(!urHr()||!pdGoalEditor)return;const t=UR.goalTemplates.find(x=>x.id===pdGoalEditor.id);if(!t)return;if(action==='duplicate'){const copy={...urClone(t),id:urUid('goal-tpl'),name:t.name+' (Copy)',status:'Draft',version:1};UR.goalTemplates.push(copy);urAudit('Goals template duplicated: '+t.id);pdViewGoalTemplate(copy.id)}else if(action==='archive'){modal('Archive Goals Template?','',`<div class="modalbody"><p>Existing assessment snapshots remain unchanged. Archived templates cannot be selected for new stages.</p></div>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="pdArchiveGoalTemplate('${t.id}')">Archive Template</button>`)}}
function pdArchiveGoalTemplate(id){if(!urHr())return;const t=UR.goalTemplates.find(x=>x.id===id);if(!t)return;t.status='Archived';urAudit('Goals template archived: '+id);closeModal();pdViewGoalTemplate(id)}
function pdGoalTemplatePage(){if(!urHr()||!pdGoalEditor)return urEmpty('Template unavailable','HR access is required.');const t=pdGoalEditor,details=pdView==='goalDetails',readonly=details||pdGoalPreview;return pdBack("urGo(()=>{pdView='';render()})",'Back to Goals Templates')+pdHead(pdGoalPreview?'Goals Template Preview':details?'Goals Template Details':t.original?'Create Goals Template Version':'Goals Template Builder',pdGoalPreview?'Preview the quantitative assessment indicators.':'Configure measurable performance outcomes and explicit scoring criteria.',details?`<button onclick="pdGoalPreview=!pdGoalPreview;render()">Preview</button><button onclick="pdGoalTemplateAction('duplicate')">Duplicate</button>${t.status!=='Archived'?'<button onclick="pdGoalTemplateAction(\'archive\')">Archive</button>':''}<button class="primary" onclick="pdEditGoalTemplate('${t.id}')">Edit Template</button>`:`<button onclick="pdGoalPreview=!pdGoalPreview;render()">${pdGoalPreview?'Back to Builder':'Preview'}</button>${!pdGoalPreview?'<button onclick="pdSaveGoalTemplate(\'Draft\')">Save as Draft</button><button class="primary" onclick="pdSaveGoalTemplate(\'Published\')">Publish Template</button>':''}`)+`<div class="urbuilder"><section class="panel pd-form"><h2>Basic Information</h2><label>Template Name *<input maxlength="120" value="${esc(t.name)}" ${readonly?'disabled':''} oninput="pdGoalField('name',this.value)"></label><label>Description<textarea rows="3" ${readonly?'disabled':''} oninput="pdGoalField('description',this.value)">${esc(t.description)}</textarea></label><label>Applicable Position / Role *<input list="pdPositions" value="${esc(t.position)}" ${readonly?'disabled':''} oninput="pdGoalField('position',this.value)"><datalist id="pdPositions">${[...new Set([...data.employees.map(e=>e[2]),'UI/UX Designer'])].map(v=>`<option>${esc(v)}</option>`).join('')}</datalist></label></section><section class="pd-indicators"><h2>Performance Indicators</h2><p class="urmuted">Weights total 100%. Each indicator defines its direction and scoring criteria on a five-point scale.</p>${t.indicators.map((x,i)=>`<section class="panel pd-form"><div class="pd-section-head"><h3>Indicator ${i+1}</h3>${!readonly?`<button onclick="pdGoalEditor.indicators.splice(${i},1);urDirty=true;render()">Remove</button>`:''}</div><div class="formgrid">${[['Indicator Name','name','text'],['Description','description','textarea'],['Measurement Unit','unit','unit'],['Target Value','target','number'],['Weight (%)','weight','number'],['Achievement Direction','direction','direction'],['Score when target met (1–5)','scoreMet','number'],['Score below target (1–5)','scoreBelow','number']].map(([label,key,type])=>`<label>${label}${['unit','direction'].includes(type)?`<select ${readonly?'disabled':''} onchange="pdSetIndicator(${i},'${key}',this.value)">${pdOptions(type==='unit'?['Percentage','Count','Days','Hours','Currency']:['Higher','Lower'],x[key])}</select>`:`<input type="${type}" ${type==='number'?'min="0" step="0.1"':''} value="${esc(String(x[key]))}" ${readonly?'disabled':''} oninput="pdSetIndicator(${i},'${key}',this.value)">`}</label>`).join('')}</div><small>${x.direction==='Lower'?'At or below':'At or above'} the target earns ${x.scoreMet}/5; otherwise ${x.scoreBelow}/5. ${x.direction==='Lower'?'Lower is better; no inverse division is used.':'Achievement = actual ÷ target × 100; a zero target uses Target Met.'}</small></section>`).join('')}${!readonly?'<button onclick="pdGoalEditor.indicators.push(pdIndicator());urDirty=true;render()">+ Add Indicator</button>':''}</section><div id="pdGoalError" class="urerror" role="alert"></div></div>`}

/* 202 Files: append-only observations using existing employee identities. */
function pdOpenJournal(id){if(!pdCanJournal(id))return;urGo(()=>{page='202 Files';pdEmployee=id;pdView='journal';pdQuery='';pdType='All types';pdFrom='';pdTo='';render()})}
const pdEntryTypes=['Achievement','Performance Observation','Area for Improvement','Coaching / Feedback','Performance Incident','Other'];
function pdJournalPage(){if(viewRole==='Employee')return urEmpty('202 Files unavailable','Your role does not have access to performance journals.');if(pdView==='entry')return pdEntryPage();if(pdView==='journal'&&pdCanJournal(pdEmployee)){const p=urPerson(pdEmployee),entries=UR.journal.filter(x=>x.employee===p.id&&(x.title+' '+x.description).toLowerCase().includes(pdQuery.toLowerCase())&&(pdType==='All types'||x.type===pdType)&&(!pdFrom||x.date>=pdFrom)&&(!pdTo||x.date<=pdTo)).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));return pdBack("pdView='';pdQuery='';render()",'Back to 202 Files')+pdHead('202 File',p.name+' · '+p.position,'<button class="primary" onclick="pdView=\'entry\';render()">Add Entry</button>')+`<section class="panel pd-form"><div class="ursummarygrid">${[['Employee ID',p.id],['Department',p.department],['Assigned Manager',pmsManagerName(p.id)]].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div></section><section class="panel"><div class="toolbar urtoolbar">${pmsToolbarSearch('Search journal entries',pdQuery,"pdQuery=this.value;render()")}${pmsToolbarSelect('Entry Type',pdType,['All types',...pdEntryTypes],"pdType=this.value;render()")}${[['From','pdFrom',pdFrom],['To','pdTo',pdTo]].map(([label,key,value])=>`<label class="urfilter">${label}<input type="date" value="${esc(value)}" onchange="${key}=this.value;render()"></label>`).join('')}</div><div class="pd-journal">${entries.map(x=>`<article><div class="pd-section-head"><span class="pill blue">${esc(x.type)}</span><time>${date(x.date)}</time></div><h3>${esc(x.title)}</h3><small>Recorded by ${esc(urPerson(x.author).name)} · Created ${date(x.created.slice(0,10))}${x.cycle?' · '+esc(urCycle(x.cycle)?.name||'Historical cycle'):''}</small><p>${esc(x.description)}</p></article>`).join('')||'<div class="empty">No journal entries match these filters.</div>'}</div></section>`}
 const rows=pdScopedEmployees().filter(e=>e.slice(0,5).join(' ').toLowerCase().includes(pdQuery.toLowerCase()));const visible=pdSlice('pd-journals',rows,pdQuery);return pdHead('202 Files','Confidential employee performance journals and supporting observations.')+`<section class="panel pms-list-panel"><div class="toolbar urtoolbar">${pmsToolbarSearch('Search employee, ID, department, or position',pdQuery,"pdQuery=this.value;render()")}</div>${pdTable(['EMPLOYEE ID','EMPLOYEE NAME','DEPARTMENT','POSITION','ASSIGNED MANAGER','ENTRIES','LAST UPDATED'],visible.map(e=>{const es=UR.journal.filter(x=>x.employee===e[0]).sort((a,b)=>b.created.localeCompare(a.created));return `<tr ${pdClickable(`pdOpenJournal('${e[0]}')`)}><td>${esc(e[0])}</td><td>${urDisplayPerson(e[0])}</td><td>${esc(e[3])}</td><td>${esc(e[2])}</td><td>${esc(pmsManagerName(e[0]))}</td><td>${es.length}</td><td>${es.length?date(es[0].date):'No entries'}</td></tr>`}).join(''),'pd-journals',rows.length,'render')}</section>`}
function pdEntryPage(){if(!pdCanJournal(pdEmployee))return urEmpty('Journal unavailable','This employee is outside your scope.');return pdBack("pdView='journal';render()",'Back to 202 File')+pdHead('Add Journal Entry',urPerson(pdEmployee).name+' · Record a performance observation.')+`<form id="pdEntryForm" class="panel pd-form" onsubmit="event.preventDefault();pdSaveEntry(this)"><div class="formgrid"><label>Entry Date *<input name="date" type="date" required value="${pdDate()}"></label><label>Entry Type *<select name="type">${pdOptions(pdEntryTypes,'Performance Observation')}</select></label><label class="full">Title *<input name="title" required maxlength="160"></label><label class="full">Description / Observation *<textarea name="description" required rows="6" maxlength="5000"></textarea></label><label>Recorded By<input readonly value="${esc(urPerson(urUser()).name)}"></label><label>Related Evaluation Cycle<select name="cycle"><option value="">No related cycle</option>${UR.cycles.filter(c=>c.participants.includes(pdEmployee)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label></div><p class="urmuted">Entries retain their original author and creation date. They support evaluation conversations and do not automatically change scores.</p><div class="urerror" id="pdEntryError" role="alert"></div><div class="pd-form-footer"><button type="button" onclick="pdView='journal';render()">Cancel</button><button class="primary">Save Entry</button></div></form>`}
function pdSaveEntry(form){if(!pdCanJournal(pdEmployee))return;const f=new FormData(form),entry={id:urUid('journal'),employee:pdEmployee,date:String(f.get('date')||''),type:String(f.get('type')||''),title:String(f.get('title')||'').trim(),description:String(f.get('description')||'').trim(),cycle:String(f.get('cycle')||''),author:urUser(),created:pdNow()};if(!/^\d{4}-\d{2}-\d{2}$/.test(entry.date)||!entry.title||!entry.description||!pdEntryTypes.includes(entry.type)||entry.cycle&&!UR.cycles.some(c=>c.id===entry.cycle&&c.participants.includes(pdEmployee))){$('#pdEntryError').textContent='Complete the required fields and select a valid related cycle.';return}UR.journal.push(entry);urAudit('202 File entry created: '+entry.id);pdView='journal';render();toast('Journal entry saved')}

/* Sequential stages preserve legacy cycle records while new cycles use stage snapshots. */
function pdStageReviewer(stage,subject){return stage.type==='Self'?subject:stage.type==='Manager'?urSupervisor(subject):stage.reviewers?.[subject]||stage.reviewer}
function pdStageRows(c,subject){return UR.assignments.filter(a=>a.cycle===c.id&&a.subject===subject)}
function pdUnlocked(a){const c=urCycle(a.cycle);if(!c?.stages||!a.stage)return true;const index=c.stages.findIndex(s=>s.id===a.stage);return index>=0&&c.stages.slice(0,index).every(s=>{const rows=pdStageRows(c,a.subject).filter(x=>x.stage===s.id);return rows.length>0&&rows.every(x=>['Submitted','Completed'].includes(x.state))})}
function pdGenerate(c){if(UR.assignments.some(a=>a.cycle===c.id))return;for(const stage of c.stages)for(const subject of c.participants){const template=(c.pendingSnapshots?.behavioral||UR.templates).find(t=>t.id===stage.behavioralTemplate)||{id:'none',name:'Goals performance only',description:'',version:1,sections:[],questions:[]};UR.assignments.push({id:urUid('rev'),cycle:c.id,subject,reviewer:pdStageReviewer(stage,subject),type:stage.type,stage:stage.id,deadline:stage.deadline,template:urClone(template),goalsTemplate:urClone((c.pendingSnapshots?.goals||UR.goalTemplates).find(t=>t.id===stage.goalsTemplate)||null),state:'Not Started',answers:{},actuals:{},updated:urToday})}}
urGenerateAssignments=function(c){return c.stages?pdGenerate(c):pdOld.generate(c)};
urCanEdit=function(a){return !!a&&pdUnlocked(a)&&pdOld.edit(a)};
urCanRead=function(a){if(!a)return false;if(!a.stage)return pdOld.read(a);if(a.reviewer===urUser())return true;return pdUnlocked(a)&&!urAnon(a)&&(urHr()||viewRole==='Manager'&&urTeam(a.subject)||urCycle(a.cycle).released&&a.subject===urUser())};
urEffective=function(a){return a.stage&&!pdUnlocked(a)?'Locked':pdOld.effective(a)};
urStartWizard=function(id,fresh=false){if(id&&urCycle(id)?.status!=='Draft')return;pdView='';pdOld.start(id,fresh);if(!urHr()||!urWizard)return;if(!id&&!urWizard.stages){urWizard.stages=['Self','Manager','HR'].map((type,i)=>({id:urUid('stage'),name:pdLabel[type],type,reviewer:type==='HR'?'HR-001':'',deadline:['2026-11-06','2026-11-11','2026-11-15'][i],goalsTemplate:'',behavioralTemplate:''}));urWizard.deadline='2026-11-15';urWizard.weights={goals:60,behavioral:40};render()}};
function pdCycleErrors(c,step=6){const errors=[];if(!c.name.trim())errors.push('Enter a cycle name.');if(!c.periodStart||!c.periodEnd||c.periodStart>c.periodEnd)errors.push('Check the evaluation period.');if(!c.start||!c.deadline||c.start>c.deadline)errors.push('Check the cycle operating dates.');if(step>=2&&(!c.participants.length||c.participants.some(id=>!pdScopedEmployees().some(e=>e[0]===id))))errors.push('Select authorized employees.');if(step>=3){if(!c.stages?.length)errors.push('Add at least one assessment stage.');for(const [i,stage] of (c.stages||[]).entries()){if(!stage.name.trim()||!['Self','Manager','HR','Peer','Upward'].includes(stage.type))errors.push('Enter each stage name and type.');if(!stage.deadline||stage.deadline<c.start||stage.deadline>c.deadline||i&&stage.deadline<=c.stages[i-1].deadline)errors.push('Each stage needs a deadline within operating dates, strictly after its preceding stage.')}}if(step>=4){for(const stage of c.stages){for(const subject of c.participants){const reviewer=pdStageReviewer(stage,subject);if(!urPeople().some(p=>p.id===reviewer)||stage.type==='Self'&&reviewer!==subject||stage.type!=='Self'&&reviewer===subject||stage.type==='HR'&&reviewer!=='HR-001')errors.push('Assign a valid evaluator for every employee and stage.')}if(!stage.goalsTemplate&&!stage.behavioralTemplate)errors.push('Choose at least one template for each stage.');const g=UR.goalTemplates.find(t=>t.id===stage.goalsTemplate),b=UR.templates.find(t=>t.id===stage.behavioralTemplate);if(stage.goalsTemplate&&(!g||g.status!=='Published'||pdGoalTemplateErrors(g,true).length))errors.push('Select a valid published Goals Template.');if(stage.behavioralTemplate&&(!b||b.status!=='Published'||urTemplateErrors(b,true).length))errors.push('Select a valid published Behavioral Template.')}if(!c.weights||!Number.isFinite(c.weights.goals)||!Number.isFinite(c.weights.behavioral)||c.weights.goals<0||c.weights.behavioral<0||c.weights.goals+c.weights.behavioral!==100)errors.push('Goals and Behavioral weights must total 100%.')}return [...new Set(errors)]}
urCycleValidation=function(c,step){return c.stages?pdCycleErrors(c,step||6):pdOld.validation(c,step)};
function pdSetStage(i,key,value){urWizard.stages[i][key]=value;urDirty=true}
function pdMoveStage(i,delta){const list=urWizard.stages;if(!list[i+delta])return;[list[i],list[i+delta]]=[list[i+delta],list[i]];urDirty=true;render()}
function pdNextStep(step){if(step>urStep){const errors=pdCycleErrors(urWizard,step-1);if(errors.length){$('#urWizardError').textContent=errors.join(' ');return}}urStep=step;render()}
function pdStageConfig(c,templates){return c.stages.map((stage,i)=>`<section class="panel pd-form"><div class="pd-section-head"><h3>${i+1}. ${esc(stage.name)}</h3><div>${!templates?`<button aria-label="Move stage up" ${i===0?'disabled':''} onclick="pdMoveStage(${i},-1)">↑</button><button aria-label="Move stage down" ${i===c.stages.length-1?'disabled':''} onclick="pdMoveStage(${i},1)">↓</button><button onclick="urWizard.stages.splice(${i},1);urDirty=true;render()">Remove</button>`:''}</div></div><div class="formgrid">${!templates?`<label>Stage Name *<input value="${esc(stage.name)}" oninput="pdSetStage(${i},'name',this.value)"></label><label>Assessment Type<select onchange="pdSetStage(${i},'type',this.value);pdSetStage(${i},'reviewer',this.value==='HR'?'HR-001':'');render()">${pdOptions(['Self','Manager','HR','Peer','Upward'],stage.type)}</select></label><label>Stage Deadline *<input type="date" value="${stage.deadline}" min="${c.start}" max="${c.deadline}" onchange="pdSetStage(${i},'deadline',this.value)"></label>`:`<label>Goals Template<select onchange="pdSetStage(${i},'goalsTemplate',this.value)"><option value="">Not applicable</option>${UR.goalTemplates.filter(t=>t.status==='Published').map(t=>`<option value="${t.id}" ${stage.goalsTemplate===t.id?'selected':''}>${esc(t.name)} · ${esc(t.position)} · v${t.version}</option>`).join('')}</select></label><label>Behavioral Template<select onchange="pdSetStage(${i},'behavioralTemplate',this.value)"><option value="">Not applicable</option>${UR.templates.filter(t=>t.status==='Published').map(t=>`<option value="${t.id}" ${stage.behavioralTemplate===t.id?'selected':''}>${esc(t.name)} · v${t.version} — ${esc(urTemplateDescription(t))}</option>`).join('')}</select></label>`}</div>${templates?`<div class="pd-evaluators">${c.participants.map(subject=>`<label>${esc(urPerson(subject).name)} — Assigned Evaluator${['Self','Manager'].includes(stage.type)?`<input readonly value="${esc(urPerson(pdStageReviewer(stage,subject)).name)}">`:`<select onchange="urWizard.stages[${i}].reviewers??={};urWizard.stages[${i}].reviewers['${subject}']=this.value;urDirty=true"><option value="">Select evaluator</option>${urPeople().filter(p=>p.id!==subject&&(stage.type!=='HR'||p.id==='HR-001')).map(p=>`<option value="${p.id}" ${pdStageReviewer(stage,subject)===p.id?'selected':''}>${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select>`}</label>`).join('')}</div>`:''}</section>`).join('')+(!templates?'<button onclick="urWizard.stages.push({id:urUid(\'stage\'),name:\'Peer Assessment\',type:\'Peer\',deadline:\'\',reviewer:\'\',goalsTemplate:\'\',behavioralTemplate:\'\'});urDirty=true;render()">+ Add Assessment Stage</button>':'')}
urWizardPage=function(){if(!urWizard?.stages)return pdOld.wizard();const c=urWizard,steps=['General Information','Select Employees','Assessment Sequence','Evaluators & Templates','Scoring','Review & Launch'];let body='';if(urStep===1)body=`<div class="formgrid">${[['Cycle Name','name','text'],['Description','description','textarea'],['Review Period Start','periodStart','date'],['Review Period End','periodEnd','date'],['Cycle Start','start','date'],['Cycle Deadline','deadline','date']].map(([label,key,type])=>`<label>${label}${key==='description'?'':' *'}${type==='textarea'?`<textarea rows="3" oninput="urSetCycle('${key}',this.value)">${esc(c[key])}</textarea>`:`<input type="${type}" value="${esc(c[key])}" onchange="urSetCycle('${key}',this.value)">`}</label>`).join('')}<label>Review Type<select onchange="urSetCycle('type',this.value)">${pdOptions(['Standard Performance Review','360° Feedback','Probationary Review','Project-Based Review'],c.type)}</select></label></div>`;else if(urStep===2)body=`<div class="toolbar urtoolbar"><label>Search employees<input class="search" value="${esc(urEmployeeSearch)}" oninput="urEmployeeSearch=this.value;urDrawEmployeeLookup()"></label><span id="urSelectedCount"></span></div><div class="tablewrap"><table><thead><tr><th>SELECT</th><th>EMPLOYEE</th><th>ID</th><th>DEPARTMENT</th><th>POSITION</th><th>MANAGER</th></tr></thead><tbody id="urEmployeeLookup"></tbody></table></div>${pmsListFooter('pmsWizardEmployeeCount','pmsWizardEmployeePager')}`;else if(urStep===3||urStep===4)body=pdStageConfig(c,urStep===4)+(urStep===4?`<section class="panel pd-form"><h3>Feedback Confidentiality</h3><label class="urcheck"><input type="checkbox" ${c.anonymousPeer?'checked':''} onchange="urSetCycle('anonymousPeer',this.checked)">Anonymous Peer Feedback</label><label class="urcheck"><input type="checkbox" ${c.anonymousUpward?'checked':''} onchange="urSetCycle('anonymousUpward',this.checked)">Anonymous Upward Feedback</label><label>Minimum Anonymous Responses<input type="number" min="2" max="10" value="${c.threshold}" onchange="urSetCycle('threshold',Number(this.value))"></label></section>`:'');else if(urStep===5)body=`<p>Cycle-specific dimension weights. A stage using only one dimension is scored solely on that dimension.</p><div class="formgrid">${['goals','behavioral'].map(key=>`<label>${key==='goals'?'Goals Performance':'Behavioral Performance'} (%)<input type="number" min="0" max="100" value="${c.weights[key]}" onchange="urWizard.weights.${key}=Number(this.value);urDirty=true"></label>`).join('')}</div><p class="urmuted">Behavioral scores average observed numerical answers. Indicator scores use the selected template criteria and weights. Stage results remain separate; the last applicable submitted stage supplies each final dimension.</p>`;else body=`<h2>${esc(c.name)}</h2><p>${c.participants.length} employees · ${c.stages.length} stages · Goals ${c.weights.goals}% / Behavioral ${c.weights.behavioral}%</p>${pdStageTimeline(c,c.participants[0],true)}<div class="notice">Only the first stage is initially available per employee. Submission unlocks the next stage; finalization and result release remain separate HR actions.</div>`;return pdBack("urGoTab('Cycles')",'Back to Cycles')+pdHead('Create Review Cycle','Configure sequential assessments, evaluators, templates, and individual deadlines.')+`<div class="urstepper pd-wizard-steps">${steps.map((name,i)=>`<button class="${urStep===i+1?'active':''}" onclick="pdNextStep(${i+1})"><span>${i+1}</span>${name}</button>`).join('')}</div><section class="panel urwizardpanel"><div class="panelhead"><div><small>STEP ${urStep} OF 6</small><h2>${steps[urStep-1]}</h2></div></div><div class="urwizardbody">${body}</div><div class="urerror" id="urWizardError" role="alert"></div><div class="urwizardfoot"><button onclick="urSaveCycleDraft()">Save as Draft</button>${urStep>1?`<button onclick="pdNextStep(${urStep-1})">Back</button>`:''}${urStep<6?`<button class="primary" onclick="pdNextStep(${urStep+1})">Continue</button>`:`<button class="primary" onclick="urConfirmCycle('${c.start>urToday?'Scheduled':'Active'}')">${c.start>urToday?'Schedule':'Launch'} Cycle</button>`}</div></section>`};
urCommitCycle=function(state){if(!urWizard?.stages)return pdOld.commit(state);if(!urHr()||!['Active','Scheduled'].includes(state)||pdCycleErrors(urWizard).length)return;const c=urClone(urWizard);c.status=state;c.groups=[...new Set(c.stages.map(s=>s.type))];c.evaluators=c.stages.flatMap(s=>c.participants.map(subject=>({subject,type:s.type,reviewer:pdStageReviewer(s,subject)})));c.templates={};c.stageSnapshots=urClone(c.stages);const index=UR.cycles.findIndex(x=>x.id===c.id);if(index>=0&&UR.assignments.some(a=>a.cycle===c.id))return;if(index>=0)UR.cycles[index]=c;else UR.cycles.push(c);if(state==='Active')pdGenerate(c);else c.pendingSnapshots={goals:urClone(UR.goalTemplates),behavioral:urClone(UR.templates)};UR.draftCycle=null;urDirty=false;urAudit('Sequential cycle '+state+': '+c.id);closeModal();urDetail=c.id;urDetailTab='Overview';urScreen='cycle';render();toast('Sequential cycle saved')};
function pdStageTimeline(c,subject,config=false){return `<ol class="pd-stages" aria-label="Assessment sequence">${c.stages.map((stage,i)=>{const a=pdStageRows(c,subject).find(a=>a.stage===stage.id),status=config?'Configured':a?.state==='Completed'&&a.submitted?'Submitted':a?urEffective(a):'Not Started';return `<li class="${status==='Locked'?'pd-locked':''}"><span class="pd-stage-number">${i+1}</span><div><b>${esc(stage.name)}</b><small>${esc(a&&urAnon(a)&&a.reviewer!==urUser()?'Anonymous evaluator':urPerson(a?.reviewer||pdStageReviewer(stage,subject)).name)}</small><small>Due ${date(stage.deadline)}</small>${urBadge(status)}${status==='Locked'?'<small>Awaiting previous assessment</small>':a?.submitted?`<small>Submitted ${date(a.submitted)}</small>`:''}${!config&&a&&urCanRead(a)?`<button class="textbtn" onclick="urOpenReview('${a.id}')">${urCanEdit(a)?'Continue Assessment':'View Assessment'}</button>`:''}</div></li>`}).join('')}</ol>`}
function pdAchievement(x,actual){if(actual==null||actual==='')return '—';const n=Number(actual);return x.direction==='Lower'?(n<=x.target?'Target Met':'Above maximum'):x.target===0?(n>=0?'Target Met':'Below target'):(n/x.target*100).toFixed(1)+'%'}
function pdIndicatorScore(x,actual){return actual==null||actual===''?null:(x.direction==='Lower'?Number(actual)<=x.target:Number(actual)>=x.target)?x.scoreMet:x.scoreBelow}
function pdGoalsScore(a,actuals=a.actuals){if(!a.goalsTemplate)return null;const rows=a.goalsTemplate.indicators.filter(x=>actuals[x.id]!=null&&actuals[x.id]!==''),weight=rows.reduce((n,x)=>n+x.weight,0);return weight?rows.reduce((n,x)=>n+pdIndicatorScore(x,actuals[x.id])*x.weight,0)/weight:null}
function pdWeighted(goals,behavioral,weights){if(goals==null)return behavioral;if(behavioral==null)return goals;return (goals*weights.goals+behavioral*weights.behavioral)/100}
urMean=function(a){return a.stage?pdWeighted(pdGoalsScore(a),pdOld.mean(a),urCycle(a.cycle).weights):pdOld.mean(a)};
function pdQuantitative(a,readonly=false,actuals=pdActuals){if(!a.goalsTemplate)return '';return `<section class="panel"><div class="panelhead"><div><h2>Goals Performance</h2><p>${esc(a.goalsTemplate.name)} · v${a.goalsTemplate.version} · ${esc(a.goalsTemplate.position)}</p></div></div><div class="tablewrap"><table><thead><tr><th>INDICATOR</th><th>TARGET</th><th>ACTUAL RESULT</th><th>ACHIEVEMENT</th><th>SCORE</th></tr></thead><tbody>${a.goalsTemplate.indicators.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.description)} · ${x.weight}% weight</small></td><td>${x.direction==='Lower'?'Maximum ':''}${x.target}${x.unit==='Percentage'?'%':' '+esc(x.unit)}</td><td>${readonly?esc(String(actuals[x.id]??'—')):`<input class="pd-actual" type="number" min="0" step="any" aria-label="Actual result: ${esc(x.name)}" value="${esc(String(actuals[x.id]??''))}" oninput="pdActuals['${x.id}']=this.value;urDirty=true;pdRefreshScores()">`}</td><td data-pd-achievement="${x.id}">${pdAchievement(x,actuals[x.id])}</td><td data-pd-score="${x.id}">${urRating(pdIndicatorScore(x,actuals[x.id]))}</td></tr>`).join('')}</tbody></table></div><p class="pd-score-note">Scores follow this template's configured target-met / below-target criteria. Lower-is-better indicators use a maximum threshold.</p></section>`}
function pdRefreshScores(){const a=UR.assignments.find(x=>x.id===urDetail);if(!a?.goalsTemplate)return;for(const x of a.goalsTemplate.indicators){const score=document.querySelector(`[data-pd-score="${x.id}"]`),ach=document.querySelector(`[data-pd-achievement="${x.id}"]`);if(score)score.textContent=urRating(pdIndicatorScore(x,pdActuals[x.id]));if(ach)ach.textContent=pdAchievement(x,pdActuals[x.id])}}
urOpenReview=function(id){const a=UR.assignments.find(x=>x.id===id);if(!a?.stage)return pdOld.open(id);if(!urVisible(a)||!urCanRead(a))return;urGo(()=>{pdActuals=urClone(a.actuals||{});pdFeedback=a.feedback||'';pdView='';page='Reviews';urTab='Reviews';urScreen='review';urDetail=id;urAnswers=urClone(a.answers);urDirty=false;render()})};
urReviewDetail=function(){const a=UR.assignments.find(x=>x.id===urDetail);if(!a?.stage)return pdOld.detail();if(!urVisible(a)||!urCanRead(a))return urEmpty('Review unavailable','This review is outside your permissions.');const c=urCycle(a.cycle),editable=urCanEdit(a),stage=c.stages.find(s=>s.id===a.stage);return pdBack("urGoTab('Reviews')",'Back to Reviews')+pdHead('Review Details',urPerson(a.subject).name+' · '+stage.name,c.released&&urCanResult(c,a.subject)?`<button class="primary" onclick="urOpenResult('${c.id}','${a.subject}')">View Released Results</button>`:'')+`<section class="panel pd-form">${pdStageTimeline(c,a.subject)}</section>${!pdUnlocked(a)?'<div class="notice">Locked — Awaiting Previous Assessment. A missed deadline does not unlock this stage.</div>':`<div class="notice">${editable?'Complete the applicable sections and submit to unlock the next assessment.':'This assessment is read-only.'} Due ${date(a.deadline)} · ${urBadge(urEffective(a))}</div>${pdQuantitative(a,!editable,editable?pdActuals:a.actuals)}${a.template.questions.length?`<section class="panel pd-form"><h2>Behavioral Performance</h2><p>${esc(a.template.name)} · v${a.template.version}</p>${urQuestionFields(a.template,urAnswers,!editable)}</section>`:''}${editable?`<section class="panel pd-form"><label>Evaluator Summary (optional)<textarea rows="4" maxlength="3000" oninput="pdFeedback=this.value;urDirty=true">${esc(pdFeedback)}</textarea></label></section><div id="urValidation" class="urerror" role="alert"></div><div class="pd-form-footer"><button onclick="urSaveResponse()">Save Draft</button><button class="primary" onclick="urConfirmSubmit()">Submit Assessment</button></div>`:''}${urHr()&&a.state==='Submitted'&&c.status==='Active'?`<button onclick="urReopen('${a.id}')">Reopen Assessment</button>`:''}`}`};
function pdActualErrors(a){return (a.goalsTemplate?.indicators||[]).filter(x=>pdActuals[x.id]==null||pdActuals[x.id]===''||!Number.isFinite(Number(pdActuals[x.id]))||Number(pdActuals[x.id])<0).map(x=>'Enter a valid actual result for '+x.name+'.')}
urSaveResponse=function(){const a=UR.assignments.find(x=>x.id===urDetail);if(a?.stage&&urCanEdit(a)){if(Object.values(pdActuals).some(v=>v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))){toast('Actual results must be nonnegative numbers.');return}a.actuals=urClone(pdActuals);a.feedback=pdFeedback.trim()}pdOld.saveResponse()};
urConfirmSubmit=function(){const a=UR.assignments.find(x=>x.id===urDetail);if(a?.stage){const errors=pdActualErrors(a);if(errors.length){$('#urValidation').textContent=errors.join(' ');return}}pdOld.confirm()};
urSubmitResponse=function(){const a=UR.assignments.find(x=>x.id===urDetail);if(a?.stage){if(!urCanEdit(a)||pdActualErrors(a).length||a.template.questions.some(q=>q.required&&!String(urAnswers[q.id]??'').trim()))return;a.actuals=urClone(pdActuals);a.feedback=pdFeedback.trim()}pdOld.submit()};
urReopen=function(id){const a=UR.assignments.find(x=>x.id===id),c=a&&urCycle(a.cycle);if(c?.stages){const index=c.stages.findIndex(s=>s.id===a.stage);if(pdStageRows(c,a.subject).some(x=>c.stages.findIndex(s=>s.id===x.stage)>index&&x.state!=='Not Started')){toast('A later assessment has started. Reopening requires a coordinated HR correction.');return}}pdOld.reopen(id)};

function pdDimensionResults(c,id){const rows=pdStageRows(c,id).filter(a=>['Submitted','Completed'].includes(a.state)&&!urAnon(a));const last=(test)=>c.stages.slice().reverse().map(s=>rows.find(a=>a.stage===s.id&&test(a))).find(Boolean);const goals=last(a=>pdGoalsScore(a)!=null),behavioral=last(a=>pdOld.mean(a)!=null);return {rows,goals,behavioral,goalScore:goals?pdGoalsScore(goals):null,behaviorScore:behavioral?pdOld.mean(behavioral):null}}
urEmployeeResults=function(){const c=urCycle(urResultCycle),id=urResultSubject;if(!c?.stages)return pdOld.results();if(!urCanResult(c,id))return urEmpty('Results unavailable','Results have not been released to your role.');const p=urPerson(id),r=pdDimensionResults(c,id),overall=pdWeighted(r.goalScore,r.behaviorScore,c.weights);return pdBack("urGoTab('Reviews')",'Back to Reviews')+pdHead('Completed Evaluation Results',p.name+' · '+c.name)+`<section class="panel pd-form"><div class="ursummarygrid">${[['Employee',p.name],['Position',c.sample&&id==='EMP-001'?'UI/UX Designer':p.position],['Department',c.sample&&id==='EMP-001'?'Information Systems':p.department],['Evaluation Period',date(c.periodStart)+' – '+date(c.periodEnd)],['Completion Status',c.status],['Result Release Status','Results Released']].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div>${c.sample?'<p class="urmuted">Illustrative sample evaluation data. Position and department reflect the evaluation snapshot.</p>':''}</section><section class="panel pd-form"><h2>Assessment Timeline</h2>${pdStageTimeline(c,id)}</section>${r.goals?pdQuantitative(r.goals,true,r.goals.actuals):'<div class="notice">No Goals Performance score is available.</div>'}<section class="panel"><div class="panelhead"><h2>Behavioral Performance</h2></div><div class="tablewrap"><table><thead><tr><th>COMPETENCY</th>${c.stages.map(s=>`<th>${esc(s.name)}</th>`).join('')}</tr></thead><tbody>${[...new Set(r.rows.flatMap(a=>a.template.questions.filter(q=>q.type==='Rating').map(q=>q.title)))].map(title=>`<tr><td>${esc(title)}</td>${c.stages.map(stage=>{const a=r.rows.find(x=>x.stage===stage.id),q=a?.template.questions.find(q=>q.title===title&&q.type==='Rating');return `<td>${q?esc(String(a.answers[q.id]??'Not observed')):'Not applicable'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="pd-score-note">Comparison applies to shared competencies only. Not Observed and unanswered ratings are excluded.</p></section><section class="panel pd-form"><h2>Overall Performance Summary</h2><div class="pd-result-scores"><div><small>Goals Performance · ${c.weights.goals}%</small><strong>${urRating(r.goalScore)}</strong></div><div><small>Behavioral Performance · ${c.weights.behavioral}%</small><strong>${urRating(r.behaviorScore)}</strong></div><div><small>Overall Performance Score</small><strong>${urRating(overall)}</strong></div></div><p>These are this cycle's configured weights, not a system-wide rule. The final applicable submitted stage supplies each dimension; other stages remain visible as comparison.</p><p>${r.goalScore!=null&&r.behaviorScore!=null?`(${r.goalScore.toFixed(1)} × ${c.weights.goals}%) + (${r.behaviorScore.toFixed(1)} × ${c.weights.behavioral}%) = ${overall.toFixed(2)} / 5`:'Only the applicable performance dimension is scored.'}</p></section><section class="panel pd-form"><h2>Written Feedback</h2>${r.rows.filter(a=>a.feedback).map(a=>`<blockquote><b>${esc(pdLabel[a.type]||a.type)}</b><p>${esc(a.feedback)}</p></blockquote>`).join('')||'<p>No written feedback recorded.</p>'}</section>${pdCanJournal(id)?`<section class="panel pd-form"><h2>Supporting Performance Records</h2><p>Confidential journal observations provide context and do not automatically affect scores.</p><button onclick="pdOpenJournal('${id}')">View 202 File (${UR.journal.filter(x=>x.employee===id&&x.date>=c.periodStart&&x.date<=c.periodEnd).length} entries in period)</button></section>`:''}`};
const pdOldCycleDetail=urCycleDetail;
urCycleDetail=function(){const html=pdOldCycleDetail(),c=urCycle(urDetail);if(!c?.stages)return html;return html+(urDetailTab==='Overview'?`<section class="panel pd-form"><h2>Assessment Sequence</h2>${pdStageTimeline(c,c.participants[0],true)}<p>Deadlines are stage-specific. Each employee advances independently after submission.</p></section>`:'')};
pmsDashboardData=function(){const d=pdOld.dashboard();d.pending=d.pending.filter(pdUnlocked);d.mine=d.mine.filter(pdUnlocked);return d};

const pdVisibleBase=urVisible,pdResultBase=urCanResult;
urVisible=function(a){if(a.stage){const employee=data.employees.find(e=>e[0]===a.subject);if(!employee||!pmsGoalEmployeeInCompany(employee))return false}return pdVisibleBase(a)};
urCanResult=function(c,id){const employee=data.employees.find(e=>e[0]===id);return (!c.stages||employee&&pmsGoalEmployeeInCompany(employee))&&pdResultBase(c,id)};
const pdReadScoped=urCanRead;urCanRead=function(a){return urVisible(a)&&pdReadScoped(a)};
const pdEditScoped=urCanEdit;urCanEdit=function(a){return urVisible(a)&&pdEditScoped(a)};
const pdLookupEmployees=urFilteredEmployees;urFilteredEmployees=function(){return urWizard?.stages?pdLookupEmployees().filter(e=>pdScopedEmployees().some(person=>person[0]===e[0])):pdLookupEmployees()};
if(!urTypes.includes('HR'))urTypes.push('HR');if(!urStatus.includes('Locked'))urStatus.push('Locked');
const pdConfirmCycleBase=urConfirmCycle;
const pdValidateSequence=urCycleValidation;
urCycleValidation=function(c,step){const errors=pdValidateSequence(c,step);if(c.stages&&(!Number.isInteger(Number(c.threshold))||Number(c.threshold)<2||Number(c.threshold)>10))errors.push('Anonymous response threshold must be a whole number from 2 to 10.');return errors};
urConfirmCycle=function(state){if(!urWizard?.stages)return pdConfirmCycleBase(state);if(!urHr())return;const errors=urCycleValidation(urWizard);if(state==='Active'&&(urWizard.start>urToday||urWizard.deadline<urToday))errors.push('Immediate launch requires current operating dates.');if(state==='Scheduled'&&urWizard.start<=urToday)errors.push('Scheduling requires a future start date.');if(errors.length){$('#urWizardError').textContent=errors.join(' ');return}modal(state==='Active'?'Launch Review Cycle?':'Schedule Review Cycle?','',`<div class="modalbody"><p>${esc(urWizard.name)} includes ${urWizard.participants.length} employees and ${urWizard.stages.length} sequential stages per employee. Only the first stage will be available initially.</p></div>`,`<button onclick="closeModal()">Back to Setup</button><button class="primary" onclick="urCommitCycle('${state}')">${state==='Active'?'Launch Cycle':'Schedule Cycle'}</button>`)};
function pdFilteredStages(){return (page==='Reports'?pmsReportRows():pmsDashboardData().reviews).filter(a=>a.stage)}
function pdSequentialPanel(){const rows=pdFilteredStages(),active=rows.filter(a=>urCycle(a.cycle).status==='Active'&&pdUnlocked(a)&&!['Submitted','Completed'].includes(a.state));const complete=[...new Map(rows.filter(a=>a.state==='Completed'&&urCanResult(urCycle(a.cycle),a.subject)).map(a=>[a.cycle+'|'+a.subject,a])).values()];return `<section class="panel pd-form"><div class="pd-section-head"><div><h2>Sequential Assessments</h2><p>Available stages, locked stages, and completed evaluations in the selected scope and period.</p></div><button onclick="urGoTab('Reviews')">View Reviews</button></div>${active.map(a=>`<div class="taskrow"><div><b>${esc(urPerson(a.subject).name)} · ${esc(urCycle(a.cycle).stages.find(s=>s.id===a.stage).name)}</b><small>Due ${date(a.deadline)} · ${esc(urEffective(a))}</small></div>${urCanRead(a)?`<button onclick="urOpenReview('${a.id}')">${urCanEdit(a)?'Continue Assessment':'View Assessment'}</button>`:'<span>Assigned evaluator only</span>'}</div>`).join('')||'<p class="urmuted">No available assessments for these filters.</p>'}<p class="urmuted">${rows.filter(a=>!pdUnlocked(a)).length} awaiting previous assessment · ${active.filter(a=>urEffective(a)==='Overdue').length} overdue available assessments · ${complete.length} completed evaluations with released results</p>${complete.length?`<div class="tablewrap"><table><thead><tr><th>EMPLOYEE / EVALUATION</th><th>GOALS PERFORMANCE</th><th>BEHAVIORAL PERFORMANCE</th><th>OVERALL</th></tr></thead><tbody>${complete.map(a=>{const c=urCycle(a.cycle),r=pdDimensionResults(c,a.subject);return `<tr ${pdClickable(`urOpenResult('${c.id}','${a.subject}')`)}><td><b>${esc(urPerson(a.subject).name)}</b><small>${esc(c.name)}</small></td><td>${urRating(r.goalScore)}</td><td>${urRating(r.behaviorScore)}</td><td>${urRating(pdWeighted(r.goalScore,r.behaviorScore,c.weights))}</td></tr>`}).join('')}</tbody></table></div>`:''}</section>`}
pdSeed();
if(!UR.goalTemplates.some(t=>t.id==='pd-marketing-goals')){
 const indicators=[pdIndicator('Campaign deliverables completed on time','Percentage',95),pdIndicator('Qualified leads generated','Count',120),pdIndicator('Campaign conversion rate','Percentage',5),pdIndicator('Campaign reporting turnaround','Days',3,'Lower')];
 const template={id:'pd-marketing-goals',name:'Marketing Specialist Performance Indicators',description:'Campaign delivery, pipeline contribution, and reporting.',position:'Marketing Specialist',status:'Published',version:1,updated:urToday,indicators};UR.goalTemplates.push(template);
 const c=urCycle('pd-active'),rows=c?urCycleAssignments(c):[];
 if(c&&rows.every(a=>a.state==='Not Started')){c.stages.forEach(s=>s.goalsTemplate=template.id);rows.forEach(a=>a.goalsTemplate=urClone(template))}
 save();
}
for(const c of UR.cycles.filter(c=>c.workflowVersion!==2&&c.stages&&c.status==='Scheduled'&&c.start<=urToday&&c.deadline>=urToday)){c.status='Active';pdGenerate(c);urAudit('Scheduled sequential cycle opened: '+c.id)}
render=function(){
 const focused=document.activeElement,placeholder=focused?.getAttribute('placeholder'),selection=focused?.selectionStart;
 if(page==='202 Files'&&viewRole==='Employee'){page='Dashboard';pdView=''}if(pdView.startsWith('goal')&&!urHr())pdView='';
 pdOld.render();let replaced=false;
 if(page==='202 Files'){$('#content').innerHTML=pdJournalPage();replaced=true}
 else if(page==='Reviews'&&urTab==='Templates'&&pdView.startsWith('goal')){$('#content').innerHTML=pdGoalTemplatePage();replaced=true}
 else if(page==='Dashboard'||page==='Reports')$('#content').insertAdjacentHTML('beforeend',pdSequentialPanel());
 $('#nav').innerHTML=pmsSidebar();
 if(replaced){const back=document.querySelector('#content > .pd-back'),header=document.querySelector('#content > .pagehead');if(back&&header)header.prepend(back);pmsSplitPageHeader()}
 const screen=[page,urTab,urScreen,urStep,pdView,pdEmployee,pdGoalPreview,urDetail,urResultCycle,urResultSubject].join('|');
 if(screen!==pdLastScreen&&(page==='202 Files'||page==='Reviews'&&(pdView.startsWith('goal')||urWizard?.stages&&urScreen==='wizard'||urCycle(urResultCycle)?.stages&&urScreen==='result'||UR.assignments.find(a=>a.id===urDetail)?.stage&&urScreen==='review'))){const main=document.querySelector('main');if(main)main.scrollTop=0}pdLastScreen=screen;
 if(placeholder){const next=[...document.querySelectorAll('#content input[placeholder]')].find(x=>x.getAttribute('placeholder')===placeholder);if(next){next.focus();if(next.type==='text'||next.type==='search')next.setSelectionRange(selection,selection)}}
};
const pdNotifications=pmsNotificationRows;pmsNotificationRows=function(){return pdNotifications().filter(a=>urVisible(a)&&pdUnlocked(a))};
const pdExportResults=urExportResults;
urExportResults=function(id){const c=urCycle(id);if(!c?.stages)return pdExportResults(id);if(!c.released)return;const rows=c.participants.filter(subject=>urCanResult(c,subject)).map(subject=>{const r=pdDimensionResults(c,subject);return [urPerson(subject).name,c.name,urRating(r.goalScore),urRating(r.behaviorScore),urRating(pdWeighted(r.goalScore,r.behaviorScore,c.weights))]});urDownloadCsv([['Employee','Cycle','Goals Performance','Behavioral Performance','Overall Performance Score'],...rows],'hrdotnet-performance-evaluation-results.csv')};
const pdNavigate=navigate;navigate=function(destination){const go=()=>{if(destination!==page){pdView='';pdQuery='';pdStatus='All statuses'}pdNavigate(destination)};if(pdView&&urDirty)urGo(go);else go()};
const pdGoTab=urGoTab;urGoTab=function(tab){urGo(()=>{pdView='';pdGoTab(tab)})};
render();

